import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.DWfJTVRq.js";const m=JSON.parse(`{"title":"Migration","description":"These guides move an application's data into DaruDB from the embedded database it uses now, one page for each.","frontmatter":{"title":"Migration","order":1,"prev":{"text":"Changelog","link":"/changelog"},"next":{"text":"SQLite","link":"/migration/sqlite"}},"headers":[{"level":2,"title":"How a move goes","slug":"how-a-move-goes","link":"#how-a-move-goes","children":[]},{"level":2,"title":"Copying fast","slug":"copying-fast","link":"#copying-fast","children":[]},{"level":2,"title":"Guides","slug":"guides","link":"#guides","children":[]}],"relativePath":"migration/index.md","filePath":"en/migration/index.md","lastUpdated":1791015517000}`),n={name:"migration/index.md"};function s(r,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="migrating-from-another-database" tabindex="-1">Migrating from another database <a class="header-anchor" href="#migrating-from-another-database" aria-label="Permalink to &quot;Migrating from another database&quot;">​</a></h1><p>These guides move an application&#39;s data into DaruDB from the embedded database it uses now, one page for each.</p><p>To change the schema of a DaruDB file instead, see <a href="./../guide/migrations">Migrations</a> in the guide.</p><h2 id="how-a-move-goes" tabindex="-1">How a move goes <a class="header-anchor" href="#how-a-move-goes" aria-label="Permalink to &quot;How a move goes&quot;">​</a></h2><p>Every guide follows the same four steps, and the old file is never changed:</p><ol><li><strong>Declare a schema</strong> that holds what the old database holds: a collection for each table or class, and a field for each column or property. Each guide has a table of what maps to what, and of what has no counterpart yet.</li><li><strong>Copy the data</strong> with a script that opens the old file read-only through its own library and writes objects into a new DaruDB file. Copying each record&#39;s key as the object&#39;s key keeps every reference between records valid as a link.</li><li><strong>Check the copy</strong>: compare the number of records in each table or class with the number of objects in each collection, and run the <a href="./../guide/tools#check-a-file">integrity check</a> on the new file.</li><li><strong>Point the application at the new file</strong>, and keep the old one until the application has run on the new one for a while.</li></ol><h2 id="copying-fast" tabindex="-1">Copying fast <a class="header-anchor" href="#copying-fast" aria-label="Permalink to &quot;Copying fast&quot;">​</a></h2><ul><li><strong>Many objects to a transaction.</strong> The scripts write a thousand objects to each write transaction, which costs one commit for the thousand rather than one each.</li><li><strong>Deferred commits, then close.</strong> Each transaction commits without waiting for the disk, and closing the database at the end makes all of them durable at once. A copy that stops halfway, for any reason, leaves a file to delete and copy again, so nothing is lost by not waiting.</li><li><strong>No order to follow.</strong> A link may name an object that is not there yet, so collections can be copied in any order.</li></ul><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><ul><li><a href="./sqlite">SQLite</a>: tables, rows and indexes, from Rust, Node.js or Dart.</li><li><a href="./realm">Realm</a>: object schemas, links and embedded objects, with Node.js.</li></ul>',10)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
